//   글자만 · 글자 + 말투 주석 · 소리: 같은 질문 4개를 낱말로 채점


const SR = 16000; // 말소리 표본화율 (16 kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
