      const b = new Float32Array(n + Math.floor(0.15 * SR));
      for (let i = 0; i < n; i++) b[i] = 0.3 * gauss(rnd) * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
      out.push(b);
    }
  }
  return concat(out);
}

const CALL: Array<[string, string, { pace?: number; amp?: number; parts?: string[]; bg?: string }]> = [
  ["A", "한빛치과입니다. 무엇을 도와드릴까요?", {}],
  ["C", "안녕하세요. 내일 오후 세 시 스케일링 예약을 확인하려고요.", {}],
  ["A", "네, 김민준 님. 내일 오후 세 시로 예약되어 있습니다.", {}],
  ["C", "저기 그게요 혹시 네 시로 바꿀 수 있을까요?", { parts: ["저기", "그게요", "혹시 네 시로 바꿀 수 있을까요?"], bg: "baby" }], // 머뭇 + 아기 울음
  ["A", "죄송합니다. 내일 네 시는 예약이 모두 찼습니다.", {}],
  ["C", "네, 알겠습니다. 괜찮습니다.", { pace: 1.5, amp: 0.7, bg: "cough" }], // 글자는 공손, 말투는 빠르고 큼
];
const TURNS: Turn[] = CALL.map(([who, text, kw], i) => ({ who, text, wav: voice(text, kw.pace ?? 1, kw.amp ?? 0.3, kw.parts, kw.bg, i) }));
const CALL_WAV = concat(TURNS.map((u) => concat([u.wav, new Float32Array(Math.floor(0.4 * SR))])));
const CALL_SEC = CALL_WAV.length / SR;

interface Cues {
  pace: number;
  pause: number;
  db: number;
  bg: string | null;
}

function hear(y: Float32Array): Cues {
  // [대체] 소리 인코더 대신: 소리에서 바로 읽는 단서 네 가지 — 말속도 · 가장 긴 쉼 · 크기 · 주변 소리
  const n = Math.floor(y.length / 320);
  const r: number[] = [];
  let rmax = 0;
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 320; i++) s += y[f * 320 + i] ** 2;
    r.push(Math.sqrt(s / 320));
    rmax = Math.max(rmax, r[f]);
  }
  const sp: number[] = [];
  let noisy = 0;
  for (let f = 0; f < n; f++) {
    if (r[f] <= 0.05 * rmax) continue;
    let z = 0;
    for (let i = 1; i < 320; i++) if (y[f * 320 + i] < 0 !== y[f * 320 + i - 1] < 0) z++;
    if (z / 319 <= 0.25) sp.push(f); // 말(톤) 조각
    else noisy += 0.02; // 잡음 같은 소리가 난 시간(초)
  }
  let onsets = 1;
  let maxGap = 0;
  let longGaps = 0;
  for (let i = 1; i < sp.length; i++) {
    const g = (sp[i] - sp[i - 1] - 1) * 0.02;
    if (sp[i] - sp[i - 1] > 1) onsets++;
    maxGap = Math.max(maxGap, g);
    if (g > 0.3) longGaps += g;
  }
  const talk = (sp[sp.length - 1] - sp[0] + 1) * 0.02 - longGaps;
  const mean = sp.reduce((s, f) => s + r[f], 0) / sp.length;
  return { pace: onsets / talk, pause: maxGap, db: 20 * Math.log10(mean), bg: noisy >= 0.8 ? "아기 울음" : noisy >= 0.2 ? "기침" : null };
}

function grade(answer: string, must: string[], mustNot: string[]): boolean {
  // 답에 꼭 있어야 할 낱말이 하나라도 있고, 있으면 안 되는 낱말이 없으면 맞음
  return must.some((m) => answer.includes(m)) && !mustNot.some((m) => answer.includes(m));
}


interface Q {
  cat: string;
  q: string;
  must: string[];
  mustNot: string[];
}

const QSET: Q[] = [
  { cat: "내용", q: "손님은 예약 시각을 몇 시로 바꾸고 싶어 했나요?", must: ["네 시", "4시"], mustNot: [] },
  { cat: "머뭇거림", q: "손님이 머뭇거린 곳이 있나요?", must: ["머뭇", "망설"], mustNot: ["없습니다"] },
  { cat: "주변 소리", q: "손님 쪽에서 들린 주변 소리가 있나요?", must: ["아기", "기침"], mustNot: ["없음", "알 수 없"] },
  { cat: "말과 말투", q: "마지막 '괜찮습니다'는 정말 괜찮다는 뜻이었나요?", must: ["확인", "불편", "아닐"], mustNot: ["괜찮다는 뜻입니다"] },
];
const UNKNOWN = "받아쓴 글만으로는 알 수 없습니다.";

interface Notes {
  pause?: number;
  bg?: string | null;
  pace?: number;
  basePace?: number;
}

function llm(cat: string, transcript: string, notes: Notes): string {
  // [대체] LLM 대신 규칙: 자기가 받은 자료(글자 · 말투 주석 · 소리 단서)에 있는 것만 답하고, 없으면 '알 수 없음'
  if (cat === "내용") return transcript.includes("네 시") ? "네 시로 바꾸고 싶어 했습니다." : UNKNOWN;
  if (cat === "머뭇거림") return (notes.pause ?? 0) >= 0.7 ? `네, 쉼이 ${(notes.pause as number).toFixed(1)}초 있어 머뭇거렸습니다.` : UNKNOWN;
  if (cat === "주변 소리") return notes.bg ? `${notes.bg} 소리가 들립니다.` : UNKNOWN;
  const fast = (notes.pace ?? 0) > 1.25 * (notes.basePace ?? 1e9);
  return fast ? "말이 빠르고 커서 정말 괜찮은지 확인이 필요합니다." : UNKNOWN;
}

const base = hear(TURNS[1].wav);
const last = hear(TURNS[5].wav);
const mid = hear(TURNS[3].wav);
const TRANSCRIPT = TURNS.map((u) => `${u.who}: ${u.text}`).join("\n");
const heard: Notes = { pause: mid.pause, bg: mid.bg ?? last.bg, pace: last.pace, basePace: base.pace };
const SYSTEMS: Record<string, Notes> = {
  "① 글자만": {},
  "② 글자 + 말투 주석": { pause: heard.pause, pace: heard.pace, basePace: heard.basePace }, // ②는 말투 숫자만, 주변 소리는 못 줌
  "③ 소리": heard,
};
const SCORE: Record<string, boolean[]> = Object.fromEntries(Object.keys(SYSTEMS).map((s) => [s, []]));
console.log(["질문 종류", ...Object.keys(SYSTEMS)].join(" | "));
for (const item of QSET) {
  const row: string[] = [];
  for (const [s, notes] of Object.entries(SYSTEMS)) {
    const ok = grade(llm(item.cat, TRANSCRIPT, notes), item.must, item.mustNot);
    SCORE[s].push(ok);
    row.push(ok ? "O" : "X");
  }
  console.log([item.cat, ...row].join(" | "));
}
console.log("점수:", Object.entries(SCORE).map(([s, v]) => `${s} ${v.filter(Boolean).length}/${v.length}`).join(", "));
check(
  grade("네 시로 바꾸고 싶어 했습니다.", ["네 시"], []) &&
    !grade("괜찮다는 뜻입니다", ["확인"], ["괜찮다는 뜻입니다"]) &&
    SCORE["① 글자만"].join() === [true, false, false, false].join() &&
    SCORE["② 글자 + 말투 주석"].join() === [true, true, false, true].join() &&
    SCORE["③ 소리"].every(Boolean),
  "글자만은 내용만, 말투 주석은 주변 소리를 못 맞히고, 소리는 모두 맞혀야 해요.",
);

trap.typescript:
// D37 · Part 3-1 · Audio LLM의 약점: 지어내기 · 비용 · 소리 원본 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d37_trap.ts   (소리·데이터는 코드 안에서 합성해요)
//   근거 없이 그럴듯하게 답하는 지어내기와 '모름' 답하기 비교, 토큰 비용


const SR = 16000; // 말소리 표본화율 (16 kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


interface Turn {
  who: string;
  text: string;
  wav: Float32Array;
}

function concat(parts: Float32Array[]): Float32Array {
  const out = new Float32Array(parts.reduce((s, p) => s + p.length, 0));
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

function hangul(s: string): number {
  return [...s].filter((c) => c >= "가" && c <= "힣").length;
}

function voice(text: string, pace: number = 1, amp: number = 0.3, parts?: string[], bg?: string, seed: number = 0): Float32Array {
  // [대체] TTS 대신: 한글 한 글자 = 220 Hz 근처 짧은 소리 하나. parts면 토막 사이에 0.8초 쉼(머뭇거림),
  // bg면 말 뒤에 주변 소리(baby: 출렁이는 잡음 1.5초 · cough: 짧은 잡음 3번)를 붙인다
  const rnd = mulberry32(seed);
  const L = Math.floor((SR * 0.2) / pace);
  const m = Math.floor(L * 0.8);
  const out: Float32Array[] = [];
  const chunks = parts ?? [text];
  chunks.forEach((chunk, k) => {
    for (let i = 0; i < hangul(chunk); i++) {
      const b = new Float32Array(L);
      for (let j = 0; j < m; j++) b[j] = amp * Math.sin((2 * Math.PI * (200 + 15 * Math.sin(i)) * j) / SR) * (0.5 - 0.5 * Math.cos((2 * Math.PI * j) / (m - 1)));
      out.push(b);
    }
    if (parts && k < chunks.length - 1) out.push(new Float32Array(Math.floor(0.8 * SR)));
  });
  if (bg === "baby") {
    const n = Math.floor(1.5 * SR);
    const b = new Float32Array(n);
    for (let i = 0; i < n; i++) b[i] = 0.25 * gauss(rnd) * (0.5 + 0.5 * Math.sin((2 * Math.PI * 2 * i) / SR));
    out.push(b);
  }
  if (bg === "cough") {
    const n = Math.floor(0.12 * SR);
    for (let c = 0; c < 3; c++) {
      const b = new Float32Array(n + Math.floor(0.15 * SR));
      for (let i = 0; i < n; i++) b[i] = 0.3 * gauss(rnd) * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
      out.push(b);
    }
  }
  return concat(out);
}

const CALL: Array<[string, string, { pace?: number; amp?: number; parts?: string[]; bg?: string }]> = [
  ["A", "한빛치과입니다. 무엇을 도와드릴까요?", {}],
  ["C", "안녕하세요. 내일 오후 세 시 스케일링 예약을 확인하려고요.", {}],
  ["A", "네, 김민준 님. 내일 오후 세 시로 예약되어 있습니다.", {}],
  ["C", "저기 그게요 혹시 네 시로 바꿀 수 있을까요?", { parts: ["저기", "그게요", "혹시 네 시로 바꿀 수 있을까요?"], bg: "baby" }], // 머뭇 + 아기 울음
  ["A", "죄송합니다. 내일 네 시는 예약이 모두 찼습니다.", {}],
  ["C", "네, 알겠습니다. 괜찮습니다.", { pace: 1.5, amp: 0.7, bg: "cough" }], // 글자는 공손, 말투는 빠르고 큼
];
const TURNS: Turn[] = CALL.map(([who, text, kw], i) => ({ who, text, wav: voice(text, kw.pace ?? 1, kw.amp ?? 0.3, kw.parts, kw.bg, i) }));
const CALL_WAV = concat(TURNS.map((u) => concat([u.wav, new Float32Array(Math.floor(0.4 * SR))])));
const CALL_SEC = CALL_WAV.length / SR;

interface Cues {
  pace: number;
  pause: number;
  db: number;
  bg: string | null;
}

function hear(y: Float32Array): Cues {
  // [대체] 소리 인코더 대신: 소리에서 바로 읽는 단서 네 가지 — 말속도 · 가장 긴 쉼 · 크기 · 주변 소리
  const n = Math.floor(y.length / 320);
  const r: number[] = [];
  let rmax = 0;
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 320; i++) s += y[f * 320 + i] ** 2;
    r.push(Math.sqrt(s / 320));
    rmax = Math.max(rmax, r[f]);
  }
  const sp: number[] = [];
  let noisy = 0;
  for (let f = 0; f < n; f++) {
    if (r[f] <= 0.05 * rmax) continue;
    let z = 0;
    for (let i = 1; i < 320; i++) if (y[f * 320 + i] < 0 !== y[f * 320 + i - 1] < 0) z++;
    if (z / 319 <= 0.25) sp.push(f); // 말(톤) 조각
    else noisy += 0.02; // 잡음 같은 소리가 난 시간(초)
  }
  let onsets = 1;
  let maxGap = 0;
  let longGaps = 0;
  for (let i = 1; i < sp.length; i++) {
    const g = (sp[i] - sp[i - 1] - 1) * 0.02;
    if (sp[i] - sp[i - 1] > 1) onsets++;
    maxGap = Math.max(maxGap, g);
    if (g > 0.3) longGaps += g;
  }
  const talk = (sp[sp.length - 1] - sp[0] + 1) * 0.02 - longGaps;
  const mean = sp.reduce((s, f) => s + r[f], 0) / sp.length;
  return { pace: onsets / talk, pause: maxGap, db: 20 * Math.log10(mean), bg: noisy >= 0.8 ? "아기 울음" : noisy >= 0.2 ? "기침" : null };
}

function grade(answer: string, must: string[], mustNot: string[]): boolean {
  // 답에 꼭 있어야 할 낱말이 하나라도 있고, 있으면 안 되는 낱말이 없으면 맞음
  return must.some((m) => answer.includes(m)) && !mustNot.some((m) => answer.includes(m));
}


// 근거 없이 그럴듯하게 답하는 '지어내기': 글자가 공손하면 "차분하고 조용했다"고 짐작하는 정책 vs 근거가 없으면 '알 수 없음'이라 답하는 정책
interface Truth {
  hesitate: boolean;
  bg: boolean;
}

function makeCall(hesitate: boolean, bg: string | undefined, seed: number): Float32Array {
  const parts = hesitate ? ["저기", "그게요", "예약을 바꿀 수 있을까요?"] : undefined;
  return voice("예약을 바꿀 수 있을까요?", 1, 0.3, parts, bg, seed);
}

// 평범한 통화 5개 + 이상한 통화 1개(머뭇 + 아기 울음)
const CASES: Array<[boolean, string | undefined]> = [[false, undefined], [false, undefined], [false, undefined], [false, undefined], [false, undefined], [true, "baby"]];
const truth: Truth[] = CASES.map(([h, b]) => ({ hesitate: h, bg: b !== undefined }));
const waves = CASES.map(([h, b], i) => makeCall(h, b, i));
const guess = (_y: Float32Array): Truth => ({ hesitate: false, bg: false }); // 글자만 보고 짐작: 늘 '평소와 같다'
const abstain = (y: Float32Array): Truth => {
  const c = hear(y); // 근거(소리 단서)가 있을 때만 답한다
  return { hesitate: c.pause >= 0.7, bg: c.bg !== null };
};
const accuracy = (policy: (y: Float32Array) => Truth, idx: number[]): number => idx.filter((i) => JSON.stringify(policy(waves[i])) === JSON.stringify(truth[i])).length / idx.length;
const normal = [0, 1, 2, 3, 4];
const odd = [5];
const all = [0, 1, 2, 3, 4, 5];
for (const [name, pol] of [["지어내기(짐작)", guess], ["근거로 답하기", abstain]] as Array<[string, (y: Float32Array) => Truth]>) {
  console.log(`${name} 평범한 통화 ${(accuracy(pol, normal) * 100).toFixed(0)}% · 이상한 통화 ${(accuracy(pol, odd) * 100).toFixed(0)}% · 전체 ${(accuracy(pol, all) * 100).toFixed(0)}%`);
}
const textTok = 40;
const audioTok = Math.ceil(2.4 * 25);
console.log(`비용: 같은 말 글자 약 ${textTok}토큰 vs 소리 ${audioTok}토큰 → ${(audioTok / textTok).toFixed(1)}배 · 소리 원본은 서버로 나간다(개인정보 주의)`);
check(accuracy(guess, normal) === 1 && accuracy(guess, odd) === 0 && accuracy(guess, all) > 0.8 && accuracy(abstain, all) === 1, "짐작은 평균 점수가 높아 보여도 이상한 통화에서 0점이에요. 평균 말고 이상한 경우를 따로 재야 해요.");

duplex.typescript:
// D37 · Part 4 · 턴 기반 vs Full-duplex 모의실험 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d37_duplex.ts   (소리·데이터는 코드 안에서 합성해요)
//   80 ms 프레임으로 세 가지 정책의 응답 지연 · 잘못 끼어듦 · 겹침 비교


const SR = 16000; // 말소리 표본화율 (16 kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


const FRAME = 0.08; // Mimi 한 프레임 = 80 ms (1초에 12.5프레임)
const USER: Array<[number, number, boolean]> = [
  [0.5, 3.0, true],
  [6.0, 7.5, false],
  [9.3, 11.0, true],
  [16.0, 17.5, true],
]; // [시작 초, 끝 초, 한 턴이 끝났나] · 6.0~11.0은 중간에 1.8초 쉬는 한 턴
const REPLY = 2.0; // 에이전트 대답 길이(초)

interface Policy {
  endpoint: number | null;
  think: number;
  stop: number;
}

const POLICY: Record<string, Policy> = {
  Cascade: { endpoint: 0.7, think: 0.9, stop: 0.4 }, // 가정한 값: 조용한 시간 endpoint · 생각 think · 끼어들기에 멈추는 데 걸리는 시간 stop
  "S2S 턴 기반": { endpoint: 0.5, think: 0.3, stop: 0.3 },
  "Full-duplex": { endpoint: null, think: 0.2, stop: 0.16 },
};

function simulate({ endpoint, think, stop }: Policy, total: number = 24.0): { delay: number; falseCut: number; back: number; overlap: number } {
  const n = Math.floor(total / FRAME);
  const user = new Array<boolean>(n).fill(false);
  for (const [s, e] of USER) for (let i = Math.round(s / FRAME); i < Math.round(e / FRAME); i++) user[i] = true;
  const plans: Array<[number, number, string, number]> = []; // 대답 계획: [시작 초, 길이 초, 종류, 손님 말이 끝난 시각]
  USER.forEach(([, e, final], i) => {
    const gap = (i + 1 < USER.length ? USER[i + 1][0] : total) - e;
    if (endpoint === null) {
      // Full-duplex: 말의 의미가 끝났을 때만 대답, 쉬는 동안엔 맞장구
      if (final) plans.push([e + think, REPLY, "reply", e]);
      else if (gap > 0.5) plans.push([e + 0.5, 0.3, "back", e]);
    } else if (gap >= endpoint) {
      plans.push([e + endpoint + think, REPLY, final ? "reply" : "false", e]); // 턴 기반: 조용한 시간이 endpoint를 넘으면 무조건 대답
    }
  });
  const agent = new Array<boolean>(n).fill(false);
  const delays: number[] = [];
  let falseCut = 0;
  let back = 0;
  for (const [s, length, kind, eUser] of plans) {
    let end = s + length;
    const again = USER.filter(([u]) => u > s && u < end).map(([u]) => u); // 대답 도중 손님이 다시 말을 시작하면 stop 뒤에 멈춤
    if (kind !== "back" && again.length) end = Math.min(end, again[0] + stop);
    for (let i = Math.round(s / FRAME); i < Math.round(end / FRAME); i++) agent[i] = true;
    if (kind === "reply") delays.push(s - eUser); // 응답 지연 = 손님 말이 끝난 뒤 대답이 시작되기까지
    if (kind === "false") falseCut++;
    if (kind === "back") back++;
  }
  const both = user.filter((u, i) => u && agent[i]).length;
  return { delay: delays.reduce((a, b) => a + b, 0) / delays.length, falseCut, back, overlap: both * FRAME };
}

const RES = Object.fromEntries(Object.entries(POLICY).map(([name, p]) => [name, simulate(p)]));
console.log("정책 | 응답 지연(초) | 잘못 끼어듦 | 맞장구 | 겹쳐 말한 시간(초)");
for (const [name, x] of Object.entries(RES)) console.log(`${name} | ${x.delay.toFixed(2)} | ${x.falseCut} | ${x.back} | ${x.overlap.toFixed(2)}`);
const c = RES["Cascade"];
const s = RES["S2S 턴 기반"];
const f = RES["Full-duplex"];
check(
  Math.abs(1 / FRAME - 12.5) < 1e-9 && f.delay < s.delay && s.delay < c.delay && c.falseCut >= 1 && s.falseCut >= 1 && f.falseCut === 0 && f.back >= 1 && f.overlap < c.overlap,
  "Full-duplex는 지연이 가장 짧고, 말 중간 쉼에 잘못 끼어들지 않고 맞장구를 쳐야 해요.",
);

streams.typescript:
// D37 · Part 4 · 두 흐름의 겹침(맞장구 vs 끼어들기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d37_streams.ts   (소리·데이터는 코드 안에서 합성해요)
//   사용자와 에이전트 두 흐름이 겹친 시간을 재고 맞장구와 끼어들기로 나누기


const SR = 16000; // 말소리 표본화율 (16 kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


const FRAME = 0.08;
const N = Math.floor(14 / FRAME);

function lane(spans: Array<[number, number]>): boolean[] {
  // (시작, 끝) 목록 → 프레임마다 말하고 있으면 true인 흐름
  const m = new Array<boolean>(N).fill(false);
  for (const [s, e] of spans) for (let i = Math.round(s / FRAME); i < Math.round(e / FRAME); i++) m[i] = true;
  return m;
}

function overlapSec(user: boolean[], agent: boolean[], frame: number = FRAME): number {
  // 두 사람이 겹쳐 말한 시간(초) = 둘 다 true인 프레임 수 x 프레임 길이
  return user.filter((u, i) => u && agent[i]).length * frame;
}

function runs(m: boolean[]): Array<[number, number]> {
  // true가 이어진 구간 [(시작 프레임, 끝 프레임), ...]
  const out: Array<[number, number]> = [];
  let start = -1;
  m.forEach((v, i) => {
    if (v && start < 0) start = i;
    if (!v && start >= 0) {
      out.push([start, i]);
      start = -1;
    }
  });
  if (start >= 0) out.push([start, m.length]);
  return out;
}

const near = (a: number, b: number): boolean => Math.abs(a - b) < 1e-9;
check(
  near(overlapSec([true, true, false, false], [false, true, true, false]), 0.08) &&
    near(overlapSec([true, true, true], [true, true, true], 0.5), 1.5) &&
    near(overlapSec([true, false, true, false], [false, true, false, true]), 0) &&
    near(overlapSec(new Array(5).fill(false), new Array(5).fill(true)), 0),
  "겹친 시간 = (둘 다 말한 프레임 수) x 프레임 길이",
);
const user = lane([[0.5, 3.0], [6.0, 7.5], [9.3, 11.0]]);
const agent = lane([[7.2, 7.6], [10.0, 12.0]]); // 7.2~7.6은 짧은 "네", 10.0~12.0은 손님 말 도중에 시작한 긴 대답
for (const [name, m] of [["손님", user], ["에이전트", agent]] as Array<[string, boolean[]]>) {
  let line = "";
  for (let k = 0; k < 14; k += 0.25) line += m[Math.floor(k / FRAME)] ? "#" : ".";
  console.log(`${name} |${line}|  (한 칸 = 0.25초)`);
}
const kinds: string[] = [];
for (const [a, b] of runs(user.map((u, i) => u && agent[i]))) {
  const dur = (b - a) * FRAME;
  kinds.push(dur <= 0.5 ? "맞장구" : "끼어들기");
  console.log(`겹침 ${(a * FRAME).toFixed(1)}초부터 ${dur.toFixed(2)}초 → ${kinds[kinds.length - 1]}`);
}
check(Math.abs(overlapSec(user, agent) - 1.3) < 0.1 && kinds.join() === "맞장구,끼어들기", "짧은 겹침(0.5초 이하)은 맞장구, 긴 겹침은 끼어들기로 나눠요.");

