# D37 · Part 5 · 정리: 핵심 공식 다시 확인 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d37_recap.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   소리 토큰 수 · 낱말 채점 · 겹친 시간 · 응답 지연 공식을 작은 함수로 확인


import base64
import io
import math
import wave

import numpy as np

SR = 16000                                   # 말소리 표본화율 (16 kHz)


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import math


def audio_tokens(sec, rate):
    return math.ceil(round(sec * rate, 9))


def overlap_sec(user, agent, frame):
    return sum(u and a for u, a in zip(user, agent)) * frame


def grade(answer, must, must_not):
    return any(m in answer for m in must) and not any(m in answer for m in must_not)


def reply_delay(endpoint, think):
    return endpoint + think


quiz = {
    "30초 통화, 1초당 50토큰 → 1500토큰": audio_tokens(30, 50) == 1500,
    "10초 x 12.5/초 = 125토큰": audio_tokens(10, 12.5) == 125,
    "겹친 프레임 3개(0.08초) = 0.24초": abs(overlap_sec([1, 1, 1, 0], [1, 1, 1, 1], 0.08) - 0.24) < 1e-9,
    "필수 낱말이 없으면 틀림": not grade("알 수 없습니다", ["아기"], []),
    "금지 낱말이 있으면 틀림": not grade("아기 울음 없음", ["아기"], ["없음"]),
    "Cascade 응답 지연 = 0.7 + 0.9 = 1.6초": abs(reply_delay(0.7, 0.9) - 1.6) < 1e-9,
}
for q, ok in quiz.items():
    print(("O " if ok else "X ") + q)
check(all(quiz.values()), "틀린 항목(X)을 위 줄에서 찾아 공식을 다시 확인하세요.")

